// 1. Telegram text (if from Telegram)
const telegramText = $json.message?.text || $json.message?.caption || '';

// 2. Identify source type and image data
const sourceType = $json.body?.sourceType || $json.sourceType || '';
const isImageSource = sourceType === 'image';

// Extract Base64 string if present across various formats
let base64Candidate =
  $json.body?.imageBase64 ||
  $json.imageBase64 ||
  $json.body?.file?.data ||
  ($json.body?.dataUrl?.includes('base64,') ? $json.body.dataUrl.split('base64,')[1] : null) ||
  ($json.body?.content?.includes('base64,') ? $json.body.content.split('base64,')[1] : null) ||
  ($json.content?.includes('base64,') ? $json.content.split('base64,')[1] : null);

if (base64Candidate && typeof base64Candidate === 'string' && base64Candidate.includes('base64,')) {
  base64Candidate = base64Candidate.split('base64,')[1];
}

// Convert Webhook base64 image to n8n $binary.data so the AI Agent receives the image binary!
let binaryData = $binary || {};
if (base64Candidate && this.helpers?.prepareBinaryData) {
  const mimeType = $json.body?.mimeType || $json.body?.file?.mimeType || $json.mimeType || 'image/jpeg';
  const fileName = $json.body?.fileName || $json.body?.file?.name || $json.fileName || 'poster.jpg';
  try {
    binaryData = {
      data: await this.helpers.prepareBinaryData(
        Buffer.from(base64Candidate, 'base64'),
        fileName,
        mimeType
      )
    };
  } catch (err) {
    // If conversion fails, keep whatever binaryData we had
  }
}

const hasImage = Boolean(binaryData?.data || $binary?.data || isImageSource || base64Candidate);

// Extract text from webhook without polluting it with raw base64 data!
let webhookText = $json.body?.text || $json.body?.prompt || $json.body?.description || $json.text || '';
if (webhookText.includes('base64,') || webhookText.startsWith('data:image/')) {
  webhookText = '';
}
const rawContent = $json.body?.content || $json.content || '';
if (rawContent && !rawContent.includes('base64,') && !rawContent.startsWith('data:image/')) {
  if (!webhookText) webhookText = rawContent;
}

const telegramChatId = $json.message?.chat?.id ? String($json.message.chat.id) : '';

// URL detection - ONLY if it's NOT an image!
let isUrl = false;
let extractedUrl = '';
if (!hasImage && !isImageSource) {
  const explicitUrl = $json.body?.url || $json.url || '';
  const textToScan = explicitUrl || webhookText || telegramText || '';
  const urlMatch = String(textToScan).match(/https?:\/\/[^\s<>"{}|]+[^\\s<>"{}|.,;:?!]/i);
  if (urlMatch) {
    extractedUrl = urlMatch[0];
    isUrl = Boolean(
      explicitUrl ||
      textToScan.trim().startsWith('http://') ||
      textToScan.trim().startsWith('https://') ||
      textToScan.trim().length <= 200
    );
  }
}

// Construct clean prompt text for the AI node
let rawInput = '';
if (hasImage || isImageSource) {
  rawInput =
    telegramText ||
    webhookText ||
    'Attached recruitment poster / flyer image. Please thoroughly inspect the poster image, headings, company name, roles, batch years, eligible branches, CGPA cutoffs, stipends/salaries, apply links, and contact emails.';
} else if (isUrl) {
  rawInput = extractedUrl;
} else {
  rawInput = telegramText || webhookText || 'Job opportunity';
}

return {
  json: {
    extracted_input: rawInput,
    extracted_url: extractedUrl,
    is_url: isUrl,
    has_image: Boolean(hasImage || isImageSource),
    telegram_chat_id: telegramChatId,
    source: telegramChatId ? 'telegram' : 'web_app',
    image_base64: base64Candidate || undefined
  },
  binary: binaryData
};

